package com.dukaops.backend.contact; import java.time.Instant; import java.util.UUID; import com.dukaops.backend.tenant.Tenant; import jakarta.persistence.*;
@Entity @Table(name="customers") public class Customer { @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="tenant_id") private Tenant tenant; private String name,phone,email,address,notes; @Enumerated(EnumType.STRING) private ContactStatus status=ContactStatus.ACTIVE; @Column(name="created_at") private Instant createdAt; @Column(name="updated_at") private Instant updatedAt; protected Customer(){} public Customer(Tenant t,String n,String p,String e,String a,String no){id=UUID.randomUUID();tenant=t;name=n;phone=p;email=e;address=a;notes=no;} @PrePersist void create(){createdAt=Instant.now();updatedAt=createdAt;} @PreUpdate void update(){updatedAt=Instant.now();} public UUID getId(){return id;} public Tenant getTenant(){return tenant;} public String getName(){return name;} public String getPhone(){return phone;} public String getEmail(){return email;} public String getAddress(){return address;} public String getNotes(){return notes;} public ContactStatus getStatus(){return status;} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;} public void update(String n,String p,String e,String a,String no){name=n;phone=p;email=e;address=a;notes=no;} public void setStatus(ContactStatus s){status=s;} }
